25	bool SameOrderedModuli(const std::vector<lbcrypto::NativeInteger>& left,
26	                       const std::vector<lbcrypto::NativeInteger>& right) {
27	    if (left.size() != right.size()) {
28	        return false;
29	    }
30	    for (std::size_t index = 0; index < left.size(); ++index) {
31	        if (left[index] != right[index]) {
32	            return false;
33	        }
34	    }
35	    return true;
36	}
