240	DoubleCKKS::DoubleCKKS(lbcrypto::CryptoContext<lbcrypto::DCRTPoly> context)
241	    : context_(std::move(context)), expectedInputScalingFactor_(0.0) {
242	    if (!context_) {
243	        Invalid("context is null");
244	    }
245	
246	    parameters_ = std::dynamic_pointer_cast<lbcrypto::CryptoParametersCKKSRNS>(context_->GetCryptoParameters());
247	    if (!parameters_) {
248	        Invalid("context is not CKKS-RNS");
249	    }
250	    if (parameters_->GetScalingTechnique() != lbcrypto::FIXEDMANUAL) {
251	        Invalid("only FIXEDMANUAL scaling is supported");
252	    }
253	
254	    const auto elementParameters = parameters_->GetElementParams();
255	    if (!elementParameters || elementParameters->GetParams().size() < 3) {
256	        Invalid("the first Mult2 lifecycle requires at least three ordered Q towers");
257	    }
258	
259	    fullModuli_.reserve(elementParameters->GetParams().size());
260	    for (const auto& towerParameters : elementParameters->GetParams()) {
261	        if (!towerParameters) {
262	            Invalid("context contains null tower parameters");
263	        }
264	        fullModuli_.push_back(towerParameters->GetModulus());
265	    }
266	    divisor_ = fullModuli_.back();
267	    if (divisor_.Mod(lbcrypto::NativeInteger(2)) != lbcrypto::NativeInteger(1)) {
268	        Invalid("the last Q tower used as q_div must be odd");
269	    }
270	    firstPairModuli_.assign(fullModuli_.begin(), fullModuli_.end() - 1);
271	
272	    const double baseScalingFactor = parameters_->GetScalingFactorReal(0);
273	    expectedInputScalingFactor_    = baseScalingFactor * baseScalingFactor;
274	    if (!std::isfinite(baseScalingFactor) || baseScalingFactor <= 0.0 ||
275	        !std::isfinite(expectedInputScalingFactor_) || expectedInputScalingFactor_ <= 0.0) {
276	        Invalid("the FIXEDMANUAL scaling factor is invalid");
277	    }
278	}
