280	void DoubleCKKS::ValidateCiphertext(const ReadOnlyCiphertext& ciphertext,
281	                                    const std::vector<lbcrypto::NativeInteger>& orderedModuli,
282	                                    std::size_t level,
283	                                    std::size_t noiseScaleDegree,
284	                                    double recordedScalingFactor,
285	                                    const std::string& keyTag,
286	                                    std::uint32_t slots,
287	                                    std::size_t componentCount,
288	                                    const char* stateLabel,
289	                                    const char* label) const {
290	    if (!ciphertext) {
291	        Invalid(std::string(label) + " is null");
292	    }
293	    if (ciphertext->GetCryptoContext().get() != context_.get()) {
294	        Invalid(std::string(label) + " belongs to a different context");
295	    }
296	    if (ciphertext->GetEncodingType() != lbcrypto::CKKS_PACKED_ENCODING) {
297	        Invalid(std::string(label) + " must use CKKS packed encoding metadata");
298	    }
299	    if (ciphertext->GetLevel() != level) {
300	        Invalid(std::string(label) + " level does not match its " + stateLabel + " state");
301	    }
302	    if (ciphertext->NumberCiphertextElements() != componentCount) {
303	        const std::string componentCountText =
304	            componentCount == 2 ? "two" : (componentCount == 3 ? "three" : std::to_string(componentCount));
305	        Invalid(std::string(label) + " must contain exactly " + componentCountText + " RLWE components");
306	    }
307	    if (ciphertext->GetNoiseScaleDeg() != noiseScaleDegree) {
308	        Invalid(std::string(label) + " noise-scale degree does not match its " + stateLabel + " state");
309	    }
310	    if (!std::isfinite(ciphertext->GetScalingFactor()) || ciphertext->GetScalingFactor() <= 0.0 ||
311	        ciphertext->GetScalingFactor() != recordedScalingFactor) {
312	        Invalid(std::string(label) + " recorded scaling factor does not match its " + stateLabel + " state");
313	    }
314	    if (ciphertext->GetKeyTag().empty() || ciphertext->GetKeyTag() != keyTag) {
315	        Invalid(std::string(label) + " key tag does not match its " + stateLabel + " state");
316	    }
317	    if (ciphertext->GetSlots() != slots) {
318	        Invalid(std::string(label) + " slots do not match its " + stateLabel + " state");
319	    }
320	
321	    const auto& expectedTowerParameters = parameters_->GetElementParams()->GetParams();
322	    if (level > fullModuli_.size() || orderedModuli.size() != fullModuli_.size() - level) {
323	        Invalid(std::string(label) + " level and active-basis size disagree");
324	    }
325	
326	    for (const auto& element : ciphertext->GetElements()) {
327	        if (element.GetFormat() != Format::EVALUATION) {
328	            Invalid(std::string(label) + " must be in evaluation format");
329	        }
330	        if (!SameOrderedModuli(OrderedModuli(element), orderedModuli)) {
331	            Invalid(std::string(label) + " ordered RNS basis mismatch");
332	        }
333	        const auto& towers = element.GetAllElements();
334	        for (std::size_t index = 0; index < towers.size(); ++index) {
335	            if (towers[index].GetRootOfUnity() != expectedTowerParameters[index]->GetRootOfUnity() ||
336	                towers[index].GetCyclotomicOrder() != expectedTowerParameters[index]->GetCyclotomicOrder()) {
337	                Invalid(std::string(label) + " tower parameters do not match the bound context");
338	            }
339	        }
340	    }
341	}
