462	void DoubleCKKS::ValidateTensorCompatibility(const CiphertextPair& left, const CiphertextPair& right) const {
463	    if (left.contextIdentity_ != right.contextIdentity_) {
464	        Invalid("Tensor2 input contexts do not match");
465	    }
466	    if (left.divisor_ != right.divisor_) {
467	        Invalid("Tensor2 input divisors do not match");
468	    }
469	    if (!SameOrderedModuli(left.orderedModuli_, right.orderedModuli_)) {
470	        Invalid("Tensor2 input ordered RNS bases do not match");
471	    }
472	    if (left.level_ != right.level_) {
473	        Invalid("Tensor2 input levels do not match");
474	    }
475	    if (left.recordedScalingFactor_ != right.recordedScalingFactor_) {
476	        Invalid("Tensor2 input recorded scaling factors do not match");
477	    }
478	    if (left.noiseScaleDegree_ != right.noiseScaleDegree_) {
479	        Invalid("Tensor2 input noise-scale degrees do not match");
480	    }
481	    if (left.lifecycle_ != right.lifecycle_) {
482	        Invalid("Tensor2 input lifecycles do not match");
483	    }
484	    if (left.keyTag_ != right.keyTag_) {
485	        Invalid("Tensor2 input key tags do not match");
486	    }
487	    if (left.slots_ != right.slots_) {
488	        Invalid("Tensor2 input slots do not match");
489	    }
490	    if (left.format_ != right.format_) {
491	        Invalid("Tensor2 input formats do not match");
492	    }
493	    if (left.componentCount_ != right.componentCount_) {
494	        Invalid("Tensor2 input component counts do not match");
495	    }
496	}
