327	void CheckKeyPolynomialBasis(
328	    const DCRTPoly& polynomial,
329	    const std::shared_ptr<lbcrypto::ILDCRTParams<lbcrypto::BigInteger>>& expectedBasis,
330	    const std::string& label) {
331	    Check(expectedBasis != nullptr, label + " expected basis is null");
332	    const auto& actualBasis = polynomial.GetParams();
333	    Check(actualBasis != nullptr && *actualBasis == *expectedBasis,
334	          label + " declared basis does not match the expected basis");
335	    const auto& expectedTowers = expectedBasis->GetParams();
336	    const auto& actualTowers = polynomial.GetAllElements();
337	    Check(actualTowers.size() == expectedTowers.size(),
338	          label + " actual tower count does not match the expected basis");
339	    for (std::size_t index = 0; index < actualTowers.size(); ++index) {
340	        Check(expectedTowers[index] != nullptr, label + " expected tower parameters are null");
341	        Check(actualTowers[index].GetCyclotomicOrder() == expectedTowers[index]->GetCyclotomicOrder() &&
342	                  actualTowers[index].GetModulus() == expectedTowers[index]->GetModulus() &&
343	                  actualTowers[index].GetRootOfUnity() == expectedTowers[index]->GetRootOfUnity(),
344	              label + " actual tower basis does not match the expected basis");
345	    }
346	}
