386	CryptoContext<DCRTPoly> MakeContext(std::uint32_t multiplicativeDepth = 3,
387	                                    std::uint32_t batchSize = 8,
388	                                    lbcrypto::KeySwitchTechnique keySwitchTechnique = lbcrypto::HYBRID,
389	                                    std::uint32_t digitSize = 0) {
390	    lbcrypto::CCParams<lbcrypto::CryptoContextCKKSRNS> parameters;
391	    parameters.SetMultiplicativeDepth(multiplicativeDepth);
392	    parameters.SetScalingModSize(30);
393	    parameters.SetFirstModSize(35);
394	    parameters.SetScalingTechnique(lbcrypto::FIXEDMANUAL);
395	    parameters.SetKeySwitchTechnique(keySwitchTechnique);
396	    parameters.SetDigitSize(digitSize);
397	    parameters.SetSecurityLevel(lbcrypto::HEStd_NotSet);
398	    parameters.SetRingDim(32);
399	    parameters.SetBatchSize(batchSize);
400	
401	    auto context = lbcrypto::GenCryptoContext(parameters);
402	    context->Enable(lbcrypto::PKE);
403	    context->Enable(lbcrypto::KEYSWITCH);
404	    context->Enable(lbcrypto::LEVELEDSHE);
405	    return context;
406	}
